#!/bin/bash
# handoff-finalize.sh — collapse the mechanical tail of /handoff into one call.
#
# Folds steps 1/2/3b/4/5/7 of the handoff skill into a single subprocess so the
# model doesn't narrate each step. Writes the thread file, handoff.json,
# regenerates INDEX files, commits HQ via explicit paths, and launches qmd
# reindex fire-and-forget via qmd-reindex-bg.sh (agent skip / laptop single-flight).
#
# Usage (all args optional):
#   handoff-finalize.sh \
#     --title "Handoff: brief description" \
#     --summary "What was accomplished" \
#     --message "User message or autogenerated" \
#     --next-steps-json '["step 1","step 2"]' \
#     --files-touched-json '["path1","path2"]' \
#     --files-touched-json-file workspace/threads/.changeset.json \
#     --learnings-json '[]' \
#     --deficiencies-json workspace/threads/.handoff-tmp/deficiencies.json \
#     --tags-json '["handoff"]' \
#     --slug "handoff-short-tag" \
#     --company "owner-slug" \
#     --next-command "/startwork"
#
# The changeset (files-touched) may be supplied inline via --files-touched-json
# OR from a file via --files-touched-json-file <path>. Prefer the file form for
# large changesets: on Windows Git Bash, CreateProcess caps a command line at
# ~32KB (~8KB under cmd.exe), so a big inline value would overflow argv as it
# rides through hq-status-summary.sh and jq. The file form keeps the giant JSON
# off argv at every hop. --files-touched-json-file wins if both are given; a
# missing file path is a hard error (exit 3). Relative paths resolve against the
# HQ root.
#
# --next-command is copied to the user's clipboard fail-soft (pbcopy /
# wl-copy / xclip) so the follow-up command is ready to paste into a fresh
# session. Defaults to "/resumework {thread_id}". Pass "" to skip the copy.
#
# Outputs JSON on stdout:
#   {"thread_id":"...","thread_path":"...","handoff_path":"...",
#    "hq_committed":true,"hq_commit_status":"committed","hq_commit_error":"",
#    "committed_paths":[...],"stage_failures":[],"indexes_regen":true,
#    "qmd_pid":12345,"next_command":"/resumework T-...","clipboard_copied":true}
#
# hq_commit_status is the honest reason behind hq_committed:
#   committed         — the handoff commit landed; committed_paths lists it
#   nothing-to-commit — no staged change existed; hq_committed:false, exit 0
#   failed            — git refused the commit; committed_paths is [],
#                       hq_commit_error carries git's message, exit 4
#   stage-failed      — git add rejected one or more paths, so the handoff is
#                       incomplete even if a commit landed for the rest; exit 4.
#                       This is the shape a held .git/index.lock takes.
# stage_failures lists paths git add rejected for a reason other than gitignore.
# On a stage failure, hq_commit_error carries git's first stderr line, and
# stage_failure_class classifies it: "permission" (the process may not write
# .git, e.g. a sandboxed run; re-run outside the sandbox), "index-lock" (another
# git process holds .git/index.lock), or "other". It is "" when nothing failed.
# index_lock_waits counts the retries of git index operations that waited for
# another process to release .git/index.lock (feedback 29213da4).
#
# --deficiencies-json <path> takes a file holding the Step 2 environment
# deficiencies array (lever, kind, severity, summary, evidence, proposed_fix).
# Items whose evidence is missing or blank are dropped before storage. A
# missing file is a hard error (exit 3). The thread also gets one system_info
# block (hq_version, hq_cli_version, host, os, hooks_enforced) with no paths,
# emails, or tokens.
#
# Exit codes: 0 ok · 2 bad argument · 3 changeset file missing · 4 handoff not
# durable (commit refused or paths unstageable) · 5 mirror failed · 6 jq is
# not installed (checked before anything is written).

set -euo pipefail

# jq builds every JSON file this script writes. Check for it before the first
# mkdir or write so a host without jq gets one clear message and an untouched
# workspace, instead of a half-written handoff and "jq: command not found".
if ! command -v jq >/dev/null 2>&1; then
  echo "handoff-finalize: jq is required but was not found on PATH. Nothing was written. Install jq (macOS: brew install jq; Debian/Ubuntu: sudo apt-get install jq; Windows: winget install jqlang.jq), then re-run /handoff." >&2
  exit 6
fi

HQ_ROOT="${HQ_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
cd "$HQ_ROOT"
# Keep both spellings of the root. The physical one is the working directory
# for git; the logical one (a symlinked checkout, macOS /var -> /private/var)
# is what absolute changeset paths from the caller are prefixed with. Both are
# stripped when paths are relativized, so a company reached through the alias
# prefix still counts when the handoff's company scope is derived
# (feedback 7a3e83c2).
HQ_ROOT_LOGICAL="$(pwd -L)"
HQ_ROOT="$(pwd -P)"
HANDOFF_SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HANDOFF_SCRIPT_DIR/lib/session-id.sh"
HAS_GIT_CHECKOUT="false"
COMMON_GIT_DIR=""
GIT_PROBE_OUTPUT=""
if GIT_PROBE_OUTPUT="$(LC_ALL=C git rev-parse --git-common-dir 2>&1)"; then
  COMMON_GIT_DIR="$GIT_PROBE_OUTPUT"
  HAS_GIT_CHECKOUT="true"
else
  GIT_PROBE_STATUS=$?
  if [[ ! -e "$HQ_ROOT/.git" && ! -L "$HQ_ROOT/.git" && \
        "$GIT_PROBE_OUTPUT" == *"not a git repository"* ]]; then
    COMMON_GIT_DIR=""
  else
    printf 'handoff-finalize: Git checkout probe failed (exit %s): %s\n' \
      "$GIT_PROBE_STATUS" "$GIT_PROBE_OUTPUT" >&2
    exit 4
  fi
fi

# -------- args --------
TITLE="Handoff: session continuation"
SUMMARY=""
MESSAGE=""
NEXT_STEPS_JSON="[]"
FILES_TOUCHED_JSON="[]"
FILES_TOUCHED_JSON_FILE=""
LEARNINGS_JSON="[]"
DEFICIENCIES_JSON_FILE=""
TAGS_JSON='["handoff"]'
SLUG="handoff"
NEXT_COMMAND="__auto__"
OWNER_COMPANY=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --company) OWNER_COMPANY="$2"; shift 2 ;;
    --title) TITLE="$2"; shift 2 ;;
    --summary) SUMMARY="$2"; shift 2 ;;
    --message) MESSAGE="$2"; shift 2 ;;
    --next-steps-json) NEXT_STEPS_JSON="$2"; shift 2 ;;
    --files-touched-json) FILES_TOUCHED_JSON="$2"; shift 2 ;;
    --files-touched-json-file) FILES_TOUCHED_JSON_FILE="$2"; shift 2 ;;
    --learnings-json) LEARNINGS_JSON="$2"; shift 2 ;;
    --deficiencies-json) DEFICIENCIES_JSON_FILE="$2"; shift 2 ;;
    --tags-json) TAGS_JSON="$2"; shift 2 ;;
    --slug) SLUG="$2"; shift 2 ;;
    --next-command) NEXT_COMMAND="$2"; shift 2 ;;
    *) echo "Unknown arg: $1" >&2; exit 2 ;;
  esac
done

# Validate inline JSON before creating even the temporary handoff directory.
# Feed values on stdin to retain the large-changeset argv limit protection.
validate_json_arg() {
  local flag="$1" value="$2"
  if ! printf '%s' "$value" | jq -e -s 'length == 1' >/dev/null 2>&1; then
    printf 'handoff-finalize: %s is not valid JSON (expected one JSON value). Nothing was written.\n' "$flag" >&2
    exit 2
  fi
}
validate_json_arg --next-steps-json "$NEXT_STEPS_JSON"
validate_json_arg --learnings-json "$LEARNINGS_JSON"
validate_json_arg --tags-json "$TAGS_JSON"
# The file form takes precedence, so do not reject an unused inline value.
if [[ -z "$FILES_TOUCHED_JSON_FILE" ]]; then
  validate_json_arg --files-touched-json "$FILES_TOUCHED_JSON"
fi

# -------- temp-file registry for off-argv JSON --------
# The Windows argv-overflow fix: any JSON value that scales with the changeset
# (the changeset itself, and the staged/skipped/committed path lists and status
# summary derived from it) is written to a temp file and fed to jq via
# --slurpfile, never via --argjson/--arg on the command line. CreateProcess caps
# a command line at ~32KB on Git Bash; even POSIX hosts cap a single argument at
# 128KB (MAX_ARG_STRLEN). A few-thousand-path changeset breaches both. Small,
# bounded values (title, ids, tags, company slugs, counts) stay inline.
#
# Temps live under workspace/threads/.handoff-tmp/ (gitignored) — not beside
# durable thread JSON — so they never flip git.dirty or baseline_noise before
# the status-summary call. Do not use /tmp (missing on some Windows Git Bash).
HANDOFF_TMP_DIR="workspace/threads/.handoff-tmp"
mkdir -p workspace/threads "$HANDOFF_TMP_DIR"
FINALIZE_TMP_FILES=()
cleanup_finalize_tmp() {
  local f
  for f in "${FINALIZE_TMP_FILES[@]:-}"; do
    [[ -n "$f" ]] && rm -f "$f"
  done
  return 0
}
trap cleanup_finalize_tmp EXIT

# new_tmp NAME: create a registered temp file under .handoff-tmp/ (Git Bash safe;
# not /tmp) and assign its absolute path to NAME in the *current* shell.
# Callers must not use VAR=$(new_tmp) — command substitution runs in a subshell,
# so FINALIZE_TMP_FILES+= would never reach the EXIT trap and temps would leak.
new_tmp() {
  local __outvar="$1"
  local t
  [[ -n "$__outvar" ]] || { echo "handoff-finalize: new_tmp requires a varname" >&2; exit 3; }
  t=$(mktemp "$HANDOFF_TMP_DIR/.handoff-XXXXXX")
  case "$t" in /*) : ;; *) t="$PWD/$t" ;; esac
  FINALIZE_TMP_FILES+=("$t")
  printf -v "$__outvar" '%s' "$t"
}

# -------- resolve changeset source to a single on-disk file --------
# Every downstream consumer of the changeset (path extraction, hq-status-summary,
# and the two jq emitters) reads it from FILES_TOUCHED_FILE, never from argv.
# --files-touched-json-file <path> wins over inline --files-touched-json; the
# inline form is materialized to a temp file so the read path is uniform.
if [[ -n "$FILES_TOUCHED_JSON_FILE" ]]; then
  if [[ ! -f "$FILES_TOUCHED_JSON_FILE" ]]; then
    echo "handoff-finalize: --files-touched-json-file not found: $FILES_TOUCHED_JSON_FILE" >&2
    exit 3
  fi
  FILES_TOUCHED_FILE="$FILES_TOUCHED_JSON_FILE"
  case "$FILES_TOUCHED_FILE" in
    /*) : ;;
    *) FILES_TOUCHED_FILE="$PWD/$FILES_TOUCHED_FILE" ;;
  esac
else
  new_tmp FILES_TOUCHED_FILE
  printf '%s' "$FILES_TOUCHED_JSON" > "$FILES_TOUCHED_FILE"
fi

# -------- changeset path extraction / validation --------
# Skipped paths accumulate as NDJSON on disk from the first record_skip — never
# rebuild a growing JSON document via jq argv/here-string (thousands of skips
# would hit Windows CreateProcess / Linux MAX_ARG_STRLEN before emit).
new_tmp SKIPPED_NDJSON_FILE
: > "$SKIPPED_NDJSON_FILE"
new_tmp SKIPPED_PATHS_FILE
printf '[]' > "$SKIPPED_PATHS_FILE"
SAFE_STAGE_PATHS=()
MIRROR_COMPANIES_JSON="[]"
MIRRORED_COMPANIES=()
MIRRORED_COMPANIES_JSON="[]"
MIRROR_STAGE_PATHS=()

record_skip() {
  local path="$1"
  local reason="$2"
  jq -nc --arg path "$path" --arg reason "$reason" \
    '{path: $path, reason: $reason}' >> "$SKIPPED_NDJSON_FILE"
}

is_sensitive_path() {
  local p="$1"
  case "$p" in
    core/settings/.gitkeep|core/settings/pure-ralph.json)
      return 1
      ;;
    .git|.git/*|.env|.env.*|*.credentials.json|*.secret.*|.hq/deploy-passwords.json|.hq/cognito-tokens.json|.claude/settings.local.json|.claude/settings.local.*|companies/*/settings/*|settings/*.json|settings/**/*.json|core/settings/*.json|core/settings/**/*.json)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

normalize_rel_path() {
  local raw="$1"
  local rel="$raw"
  if [[ "$raw" == "$HQ_ROOT/"* ]]; then
    rel="${raw#"$HQ_ROOT/"}"
  elif [[ "$raw" == "$HQ_ROOT_LOGICAL/"* ]]; then
    rel="${raw#"$HQ_ROOT_LOGICAL/"}"
  elif [[ "$raw" == /* ]]; then
    return 1
  fi
  rel="${rel#./}"
  [[ -z "$rel" ]] && return 1
  [[ "$rel" == -* || "$rel" == ".." || "$rel" == ../* || "$rel" == */../* || "$rel" == .git || "$rel" == .git/* ]] && return 1
  printf '%s\n' "$rel"
}

while IFS=$'\t' read -r raw_path deleted_flag; do
  [[ -z "${raw_path:-}" ]] && continue
  if ! rel_path=$(normalize_rel_path "$raw_path"); then
    record_skip "$raw_path" "unsafe-path"
    continue
  fi
  if is_sensitive_path "$rel_path"; then
    record_skip "$rel_path" "sensitive-path"
    continue
  fi
  if [[ ! -e "$rel_path" ]]; then
    if [[ "$HAS_GIT_CHECKOUT" == "true" && "$deleted_flag" == "true" ]] \
      && git ls-files --error-unmatch "$rel_path" >/dev/null 2>&1; then
      SAFE_STAGE_PATHS+=("$rel_path")
    else
      record_skip "$rel_path" "missing"
    fi
    continue
  fi
  SAFE_STAGE_PATHS+=("$rel_path")
done < <(
  jq -r '
    if type != "array" then empty else
      .[] |
      if type == "string" then
        [., "false"]
      else
        [(.path // ""), (((.deleted == true) or (.status == "deleted")) | tostring)]
      end | @tsv
    end
  ' "$FILES_TOUCHED_FILE" 2>/dev/null || true
)

# Company workspace mirrors have one owner. --company is explicit; otherwise the
# session binding is used. Never treat the list of touched company paths as
# recipients. Inspect the complete handoff paths, including skipped paths, so a
# missing or excluded file cannot hide that the handoff spans multiple companies.
TOUCHED_COMPANIES_JSON=$(jq -c --arg hq_root "$HQ_ROOT" --arg hq_root_logical "$HQ_ROOT_LOGICAL" '
  [ (if type == "array" then .[] else empty end)
    | (if type == "string" then . elif type == "object" and (.path | type) == "string" then .path else "" end)
    | (if startswith($hq_root + "/") then .[(($hq_root | length) + 1):]
       elif startswith($hq_root_logical + "/") then .[(($hq_root_logical | length) + 1):]
       else . end)
    | sub("^\\./"; "")
    | (try capture("^companies/(?<company>[a-z0-9][a-z0-9_-]*)/").company catch null)
    | select(type == "string")
  ] | unique
' "$FILES_TOUCHED_FILE" 2>/dev/null || printf '[]')
MIRROR_COMPANIES_JSON='[]'

bound_session_company() {
  local session_id metadata company
  session_id="$(session_id_resolve "$HQ_ROOT")"
  [[ -n "$session_id" ]] || return 0
  metadata="$HQ_ROOT/workspace/sessions/$session_id/meta.yaml"
  [[ -r "$metadata" ]] || return 0
  company="$(awk '$1 == "company_slug:" { sub(/^[^:]+:[[:space:]]*/, ""); gsub(/^"|"$/, ""); print; exit }' "$metadata" 2>/dev/null || true)"
  [[ "$company" =~ ^[a-z0-9][a-z0-9_-]*$ ]] || return 0
  printf '%s' "$company"
}

BOUND_SESSION_COMPANY="$(bound_session_company)"
if [[ -n "$OWNER_COMPANY" ]]; then
  if [[ ! "$OWNER_COMPANY" =~ ^[a-z0-9][a-z0-9_-]*$ ]] || [[ ! -d "$HQ_ROOT/companies/$OWNER_COMPANY" ]]; then
    echo "handoff-finalize: invalid or missing owner company: $OWNER_COMPANY" >&2
    exit 2
  fi
  if [[ -n "$BOUND_SESSION_COMPANY" && "$BOUND_SESSION_COMPANY" != "$OWNER_COMPANY" ]]; then
    echo "handoff-finalize: --company $OWNER_COMPANY does not match the bound session company $BOUND_SESSION_COMPANY" >&2
    exit 2
  fi
  BOUND_SESSION_COMPANY="$OWNER_COMPANY"
fi
SESSION_LOCKED_COMPANIES_JSON='[]'
if [[ -n "$BOUND_SESSION_COMPANY" ]]; then
  SESSION_ID_FOR_COMPANIES="$(session_id_resolve "$HQ_ROOT")"
  SESSION_CAP="$HQ_ROOT/workspace/sessions/$SESSION_ID_FOR_COMPANIES/scope-capability.json"
  LOCKED_COMPANIES="$BOUND_SESSION_COMPANY"
  if [[ -f "$SESSION_CAP" && -f "$HQ_ROOT/core/scripts/lib/session-scope-capability.sh" ]]; then
    # shellcheck source=lib/session-scope-capability.sh
    . "$HQ_ROOT/core/scripts/lib/session-scope-capability.sh"
    LOCKED_COMPANIES="$(session_scope_read_companies "$HQ_ROOT" "$SESSION_ID_FOR_COMPANIES" 2>/dev/null | paste -sd, -)"
  fi
  [[ -n "$LOCKED_COMPANIES" ]] && SESSION_LOCKED_COMPANIES_JSON="$(jq -cn --arg slugs "$LOCKED_COMPANIES" '$slugs | split(",") | map(select(length > 0))')"
fi
TOUCHED_COMPANY_COUNT="$(jq 'length' <<< "$TOUCHED_COMPANIES_JSON")"
if [[ "$TOUCHED_COMPANY_COUNT" -gt 1 ]]; then
  printf 'handoff-finalize: company mirror skipped (handoff spans multiple companies)\n' >&2
elif [[ -z "$BOUND_SESSION_COMPANY" || ! -d "companies/$BOUND_SESSION_COMPANY" ]]; then
  printf 'handoff-finalize: company mirror skipped (no bound company for this session)\n' >&2
elif [[ "$TOUCHED_COMPANY_COUNT" -eq 1 ]] && \
     [[ "$(jq -r '.[0]' <<< "$TOUCHED_COMPANIES_JSON")" != "$BOUND_SESSION_COMPANY" ]]; then
  printf 'handoff-finalize: company mirror skipped (handoff paths do not match the bound company)\n' >&2
else
  MIRROR_COMPANIES_JSON="$(jq -cn --arg company "$BOUND_SESSION_COMPANY" '[$company]')"
fi

# -------- bg git reap (if launched by caller) --------
GIT_BG_ERRORS=""
if [[ -f /tmp/handoff-git-bg.pid ]]; then
  PID=$(cat /tmp/handoff-git-bg.pid 2>/dev/null || true)
  if [[ -n "$PID" ]]; then
    wait "$PID" 2>/dev/null || true
    if [[ -f /tmp/handoff-git-bg.log ]]; then
      GIT_BG_ERRORS=$(grep '^ERR:' /tmp/handoff-git-bg.log 2>/dev/null || true)
    fi
  fi
  rm -f /tmp/handoff-git-bg.pid
fi

# -------- thread file --------
TS=$(date -u +%Y%m%dT%H%M%SZ)
DAY=$(date +%Y%m%d)
HM=$(date +%H%M%S)
THREAD_ID="T-${DAY}-${HM}-${SLUG}"
# Thread ids must be unique: /resumework selects by full thread id, and two
# handoffs in the same second with the same slug would otherwise share one id
# and overwrite each other (feedback_b75f1436). Probe the local thread store,
# its archive and the session's company mirrors for an existing id and append
# -2, -3, ... until free.
thread_id_taken() {
  local candidate="$1" co
  [[ -e "workspace/threads/${candidate}.json" ]] && return 0
  [[ -n "$(find workspace/threads/archive -name "${candidate}.json" -print -quit 2>/dev/null)" ]] && return 0
  local locked="${LOCKED_COMPANIES:-}"
  for co in ${locked//,/ }; do
    [[ -n "$co" && -e "companies/${co}/workspace/sessions/${candidate}.json" ]] && return 0
  done
  return 1
}
if thread_id_taken "$THREAD_ID"; then
  n=2
  while thread_id_taken "${THREAD_ID}-${n}"; do n=$((n + 1)); done
  THREAD_ID="${THREAD_ID}-${n}"
fi
THREAD_PATH="workspace/threads/${THREAD_ID}.json"
CHANGESET_PATH="workspace/threads/${THREAD_ID}.changeset.json"

BRANCH=$(git symbolic-ref --short HEAD 2>/dev/null || echo "DETACHED")
START_COMMIT=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")
DIRTY="false"
[[ -n "$(git status --porcelain 2>/dev/null)" ]] && DIRTY="true"

# Status summary and staged-path list both scale with the changeset / repo
# noise, so they are captured to files and later slurped into jq off argv.
new_tmp STATUS_SUMMARY_FILE
printf '{}' > "$STATUS_SUMMARY_FILE"
if command -v hq >/dev/null 2>&1; then
  hq core hq-status-summary --session-files-file "$FILES_TOUCHED_FILE" --json > "$STATUS_SUMMARY_FILE" 2>/dev/null \
    || printf '{}' > "$STATUS_SUMMARY_FILE"
  # Guard against a truncated/empty write masquerading as success.
  [[ -s "$STATUS_SUMMARY_FILE" ]] || printf '{}' > "$STATUS_SUMMARY_FILE"
fi
BASELINE_NOISE_COUNT=$(jq -r '.counts.baseline_noise // 0' "$STATUS_SUMMARY_FILE" 2>/dev/null || echo 0)
new_tmp STAGED_PATHS_FILE
if [[ "$HAS_GIT_CHECKOUT" == "true" ]]; then
  printf '%s\n' "${SAFE_STAGE_PATHS[@]:-}" | jq -R -s 'split("\n") | map(select(length > 0))' > "$STAGED_PATHS_FILE"
else
  printf '[]' > "$STAGED_PATHS_FILE"
fi

# -------- environment deficiencies + system_info --------
DEFICIENCIES_JSON="[]"
if [[ -n "$DEFICIENCIES_JSON_FILE" ]]; then
  if [[ ! -f "$DEFICIENCIES_JSON_FILE" ]]; then
    echo "handoff-finalize: deficiencies file not found: $DEFICIENCIES_JSON_FILE" >&2
    exit 3
  fi
  if ! DEFICIENCIES_JSON="$(jq -c '
      if type == "array" then . else [] end
      | map(select(type == "object"
          and ((.evidence // "") | type) == "string"
          and ((.evidence // "") | gsub("^\\s+|\\s+$"; "")) != ""))
      | map({lever, kind, severity, summary, evidence, proposed_fix})
    ' "$DEFICIENCIES_JSON_FILE" 2>/dev/null)"; then
    echo "handoff-finalize: deficiencies file is not valid JSON: $DEFICIENCIES_JSON_FILE" >&2
    exit 2
  fi
fi

SYSINFO_HQ_VERSION="$(sed -n 's/^hqVersion:[[:space:]]*"\{0,1\}\([^"]*\)"\{0,1\}[[:space:]]*$/\1/p' core/core.yaml 2>/dev/null | head -n 1 || true)"
SYSINFO_CLI_VERSION=""
if command -v hq >/dev/null 2>&1; then
  SYSINFO_CLI_VERSION="$(hq --version 2>/dev/null | head -n 1 | grep -oE '[0-9]+\.[0-9]+\.[0-9]+[0-9A-Za-z.+-]*' | head -n 1 || true)"
fi
case "${HQ_HANDOFF_HOST:-${CLAUDE_CODE_ENTRYPOINT:-cli}}" in
  sdk*) SYSINFO_HOST="sdk" ;;
  *desktop*) SYSINFO_HOST="desktop" ;;
  *) SYSINFO_HOST="cli" ;;
esac
SYSINFO_OS="$(uname -s 2>/dev/null | tr '[:upper:]' '[:lower:]' || true)"
SYSINFO_HOOKS="false"
if [[ -f core/scripts/check-hq-hooks.sh ]] && \
   bash core/scripts/check-hq-hooks.sh --root "$HQ_ROOT" --require-ledger >/dev/null 2>&1; then
  SYSINFO_HOOKS="true"
fi
SYSTEM_INFO_JSON="$(jq -cn \
  --arg hq_version "$SYSINFO_HQ_VERSION" \
  --arg hq_cli_version "$SYSINFO_CLI_VERSION" \
  --arg host "$SYSINFO_HOST" \
  --arg os "$SYSINFO_OS" \
  --argjson hooks_enforced "$SYSINFO_HOOKS" \
  '{hq_version: $hq_version, hq_cli_version: $hq_cli_version, host: $host, os: $os, hooks_enforced: $hooks_enforced}')"

mkdir -p workspace/threads
# Every next step carries an id and a closure status (2026-09-07). Handoffs
# used to record steps with no way to close one; an audit found a task copied
# forward through three consecutive handoffs and never started. Ids are
# `<thread_id>#<n>`; status starts "open" and is closed by
# core/scripts/handoff-open-steps.sh close. Strings and {step:...} objects are
# both accepted; already-normalized objects keep their fields.
NEXT_STEPS_NORMALIZED_JSON="$(jq -c --arg tid "$THREAD_ID" '
  to_entries | map(.key as $k |
    (if (.value|type) == "string" then {step: .value} else .value end)
    | .id = (.id // ($tid + "#" + (($k + 1)|tostring)))
    | .status = (.status // "open")
  ) | map(del(.key))' <<<"$NEXT_STEPS_JSON" 2>/dev/null || printf '%s' "$NEXT_STEPS_JSON")"

jq -n \
  --arg thread_id "$THREAD_ID" \
  --arg ts "$TS" \
  --arg root "$HQ_ROOT" \
  --arg cwd "$(pwd)" \
  --arg branch "$BRANCH" \
  --arg commit "$START_COMMIT" \
  --arg changeset_path "$CHANGESET_PATH" \
  --argjson dirty "$DIRTY" \
  --arg summary "$SUMMARY" \
  --arg title "$TITLE" \
  --argjson next_steps "$NEXT_STEPS_NORMALIZED_JSON" \
  --slurpfile files_touched "$FILES_TOUCHED_FILE" \
  --argjson learnings "$LEARNINGS_JSON" \
  --argjson deficiencies "$DEFICIENCIES_JSON" \
  --argjson system_info "$SYSTEM_INFO_JSON" \
  --argjson tags "$TAGS_JSON" \
  --argjson companies "$MIRROR_COMPANIES_JSON" \
  --argjson company_slugs "$SESSION_LOCKED_COMPANIES_JSON" \
  '{
    thread_id: $thread_id,
    version: 1,
    type: "handoff",
    created_at: $ts,
    updated_at: $ts,
    workspace_root: $root,
    cwd: $cwd,
    git: { branch: $branch, current_commit: $commit, dirty: $dirty },
    changeset_path: $changeset_path,
    conversation_summary: $summary,
    next_steps: $next_steps,
    files_touched: ($files_touched[0] // []),
    learnings: $learnings,
    deficiencies: $deficiencies,
    system_info: $system_info,
    metadata: { title: $title, tags: $tags, company: $companies, company_slugs: $company_slugs }
  }' > "$THREAD_PATH"

# `handoff-finalize.sh` writes from a shell subprocess, so its thread creation
# does not pass through editor PostToolUse hooks. Replay the installed mirror
# hook with Bash: hooks are source files and do not require an executable bit.
MIRROR_HOOK="$HQ_ROOT/.claude/hooks/mirror-thread-to-company.sh"
if [[ -f "$MIRROR_HOOK" ]]; then
  jq -n --arg file_path "$HQ_ROOT/$THREAD_PATH" \
    '{tool_name:"Write", tool_input:{file_path:$file_path}}' | \
    bash "$MIRROR_HOOK" >/dev/null 2>&1 || {
      if [[ "$MIRROR_COMPANIES_JSON" != '[]' ]]; then
        echo "handoff-finalize: company mirror failed; canonical thread retained" >&2
        exit 5
      fi
    }
elif [[ "$MIRROR_COMPANIES_JSON" != '[]' ]]; then
  echo "handoff-finalize: company mirror hook missing; canonical thread retained" >&2
  exit 5
fi
while IFS= read -r company; do
  [[ -n "$company" ]] || continue
  if [[ -f "companies/${company}/workspace/sessions/${THREAD_ID}.json" ]]; then
    MIRRORED_COMPANIES+=("$company")
    MIRROR_STAGE_PATHS+=(
      "companies/${company}/workspace/index.jsonl"
      "companies/${company}/workspace/.gitignore"
    )
  fi
done < <(jq -r '.[]' <<<"$MIRROR_COMPANIES_JSON")
MIRRORED_COMPANIES_JSON=$(printf '%s\n' "${MIRRORED_COMPANIES[@]:-}" | jq -R -s -c 'split("\n") | map(select(length > 0))')

# Materialize NDJSON skips into a JSON array for --slurpfile (stdin only; no
# growing argv). Empty NDJSON stays the [] written at init.
if [[ -s "$SKIPPED_NDJSON_FILE" ]]; then
  jq -s '.' "$SKIPPED_NDJSON_FILE" > "$SKIPPED_PATHS_FILE"
fi

jq -n \
  --arg thread_id "$THREAD_ID" \
  --arg thread_path "$THREAD_PATH" \
  --arg ts "$TS" \
  --arg title "$TITLE" \
  --arg summary "$SUMMARY" \
  --arg branch "$BRANCH" \
  --arg started_commit "$START_COMMIT" \
  --arg finalized_commit_note "The exact handoff commit is emitted by handoff-finalize.sh as commit_after_finalize; a file cannot contain the hash of the commit that contains itself." \
  --slurpfile files_touched "$FILES_TOUCHED_FILE" \
  --slurpfile staged_paths "$STAGED_PATHS_FILE" \
  --slurpfile skipped_paths "$SKIPPED_PATHS_FILE" \
  --slurpfile status_summary "$STATUS_SUMMARY_FILE" \
  '{
    thread_id: $thread_id,
    thread_path: $thread_path,
    created_at: $ts,
    intent: { title: $title, summary: $summary },
    git: {
      branch: $branch,
      started_commit: $started_commit,
      finalized_commit: null,
      finalized_commit_note: $finalized_commit_note
    },
    files_touched: ($files_touched[0] // []),
    staged_paths: ($staged_paths[0] // []),
    skipped_paths: ($skipped_paths[0] // []),
    verification: { notes: [], upstream_refs_compared: [] },
    status_summary: ($status_summary[0] // {})
  }' > "$CHANGESET_PATH"

# -------- handoff.json pointer --------
# Keep the pointer readable as one complete file at all times. The temp is in
# the destination directory so mv publishes it with a same-filesystem rename.
# The pointer path is checkout-relative so the synced handoff stays portable.
write_handoff_pointer() {
  local destination="$1" thread_path="$2" destination_dir pointer_tmp
  destination_dir="$(dirname "$destination")"
  mkdir -p "$destination_dir"
  pointer_tmp="$(mktemp "$destination_dir/.handoff-pointer.XXXXXX")"
  FINALIZE_TMP_FILES+=("$pointer_tmp")
  if ! jq -n --arg ts "$TS" --arg msg "$MESSAGE" --arg thread_id "$THREAD_ID" --arg thread_path "$thread_path" --arg summary "$SUMMARY" '{
    created_at: $ts,
    message: $msg,
    last_thread: $thread_id,
    thread_path: $thread_path,
    context_notes: $summary
  }' > "$pointer_tmp"; then
    rm -f "$pointer_tmp"
    return 1
  fi
  if ! mv -f "$pointer_tmp" "$destination"; then
    rm -f "$pointer_tmp"
    return 1
  fi
}

copy_handoff_thread() {
  local destination="$1" destination_dir thread_tmp
  destination_dir="$(dirname "$destination")"
  mkdir -p "$destination_dir"
  thread_tmp="$(mktemp "$destination_dir/.handoff-thread.XXXXXX")"
  FINALIZE_TMP_FILES+=("$thread_tmp")
  if ! cp "$HQ_ROOT/$THREAD_PATH" "$thread_tmp"; then
    rm -f "$thread_tmp"
    return 1
  fi
  if ! mv -f "$thread_tmp" "$destination"; then
    rm -f "$thread_tmp"
    return 1
  fi
}

write_handoff_pointer "workspace/threads/handoff.json" "$THREAD_PATH"
if [[ "$HAS_GIT_CHECKOUT" == "true" ]]; then
  case "$COMMON_GIT_DIR" in
    /*|[A-Za-z]:/*) ;;
    *) COMMON_GIT_DIR="$HQ_ROOT/$COMMON_GIT_DIR" ;;
  esac
  MAIN_CHECKOUT_ROOT="$(cd "$COMMON_GIT_DIR/.." && pwd -P)"
  if [[ "$MAIN_CHECKOUT_ROOT" != "$HQ_ROOT" ]]; then
    copy_handoff_thread "$MAIN_CHECKOUT_ROOT/$THREAD_PATH"
    write_handoff_pointer "$MAIN_CHECKOUT_ROOT/workspace/threads/handoff.json" "$THREAD_PATH"
  fi
fi

# -------- regen INDEX files via dedicated scripts --------
# Inline INDEX regen replaced with delegations to reusable bash scripts.
# Index regen is also callable independently (e.g. /cleanup --reindex,
# handoff-post.sh). Zero Claude context either way.
hq core rebuild-index threads --both >/dev/null 2>&1 || true
hq core rebuild-index orchestrator >/dev/null 2>&1 || true

# -------- INDEX.md top-level timestamp only --------
if [[ -f INDEX.md ]]; then
  # Bump 'Generated:' line in place if present, else skip
  if grep -q '^Generated:' INDEX.md; then
    tmpf=$(mktemp)
    awk -v ts="$TS" '/^Generated:/ { print "Generated: " ts; next } { print }' INDEX.md > "$tmpf"
    mv "$tmpf" INDEX.md
  fi
fi

# -------- HQ commit (explicit paths only — never git add -A) --------
# A failed commit must never ride inside a success payload. hq_committed alone
# cannot say why it is false — "there was nothing to commit" and "git refused
# the commit" are the same value — so hq_commit_status carries the reason and a
# genuine failure also exits non-zero (4).
HQ_COMMITTED="false"
HQ_COMMIT_STATUS="nothing-to-commit"
if [[ "$HAS_GIT_CHECKOUT" != "true" ]]; then
  HQ_COMMIT_STATUS="no-git-checkout"
fi
HQ_COMMIT_ERROR=""
EXPLICIT_PATHS=(
  "${SAFE_STAGE_PATHS[@]:-}"
  "${MIRROR_STAGE_PATHS[@]:-}"
  "workspace/threads/${THREAD_ID}.json"
  "workspace/threads/${THREAD_ID}.changeset.json"
  "workspace/threads/handoff.json"
  "workspace/threads/recent.md"
  "workspace/threads/INDEX.md"
  "workspace/orchestrator/INDEX.md"
  "INDEX.md"
)
STAGED=0
# Big files and swept-in media never ride a handoff commit (feedback_c682f3ad).
# A changeset that names a project folder used to stage every render under it,
# and the HQ root history grew by gigabytes a day. Two rules, applied to what
# each `git add` actually staged:
#   - any file above HQ_OFFLOAD_MIN_BYTES (default 50 MiB, the same cap the
#     autosave hook uses) is unstaged, named or not;
#   - a media or archive file that only arrived because its parent directory
#     was listed is unstaged at any size. A media file the changeset names
#     directly is the agent's explicit choice and still commits.
# HQ_HANDOFF_ALLOW_MEDIA=1 turns off the second rule. Every unstaged path is
# reported in skipped_paths with reason "oversize" or "media-in-directory".
HANDOFF_MAX_BYTES="${HQ_OFFLOAD_MIN_BYTES:-52428800}"
[[ "$HANDOFF_MAX_BYTES" =~ ^[0-9]+$ && "$HANDOFF_MAX_BYTES" -gt 0 ]] || HANDOFF_MAX_BYTES=52428800
HANDOFF_STAGE_SKIPS=0
# Paths whose `git add` succeeded, NUL-separated. The filter runs once after the
# staging loop: a per-path pass costs a git process per entry, which a
# 5000-path changeset cannot afford. HANDOFF_ADDED_PATHS holds the same paths
# normalized (see handoff_norm_path), one per line, to match git's spelling.
# The same list drives the commit: it is restricted to exactly these paths, so
# anything another process left in the index stays staged and out of the
# handoff commit (feedback 25b250a7). OWN_STAGED_FILE is the name the commit
# step uses for it.
new_tmp HANDOFF_ADDED_PATHS_FILE
: > "$HANDOFF_ADDED_PATHS_FILE"
OWN_STAGED_FILE="$HANDOFF_ADDED_PATHS_FILE"
HANDOFF_ADDED_PATHS=""
# hq_git_index_retry <git args...> — run a git command that takes the index
# lock. When it fails because another process holds .git/index.lock (concurrent
# sessions commit their own handoff checkpoints in the same minute, feedback
# 29213da4), wait with a short backoff and try again, up to
# HQ_HANDOFF_INDEX_LOCK_RETRIES times (default 8, about 6 s in total). Any other
# failure, and a lock that outlives the retries, returns git's status with its
# stderr intact so the caller classifies it.
HQ_HANDOFF_INDEX_LOCK_RETRIES="${HQ_HANDOFF_INDEX_LOCK_RETRIES:-8}"
[[ "$HQ_HANDOFF_INDEX_LOCK_RETRIES" =~ ^[0-9]+$ ]] || HQ_HANDOFF_INDEX_LOCK_RETRIES=8
HQ_HANDOFF_INDEX_LOCK_WAITS=0
new_tmp HQ_RETRY_ERR_FILE
hq_git_index_retry() {
  local attempt=0 rc=0 delay
  while :; do
    rc=0
    "$@" 2>"$HQ_RETRY_ERR_FILE" || rc=$?
    if [[ $rc -eq 0 ]] || ! grep -q 'index\.lock' "$HQ_RETRY_ERR_FILE" 2>/dev/null \
       || [[ $attempt -ge $HQ_HANDOFF_INDEX_LOCK_RETRIES ]]; then
      cat "$HQ_RETRY_ERR_FILE" >&2
      return $rc
    fi
    attempt=$((attempt+1))
    HQ_HANDOFF_INDEX_LOCK_WAITS=$((HQ_HANDOFF_INDEX_LOCK_WAITS+1))
    # 0.1, 0.2, 0.4, 0.8, then 1 s per try; capped so a lock that is never
    # released still ends in a classified stage-failed within seconds.
    case $attempt in 1) delay=0.1 ;; 2) delay=0.2 ;; 3) delay=0.4 ;; 4) delay=0.8 ;; *) delay=1 ;; esac
    sleep "$delay"
  done
}
# Set when the filter could not run or could not unstage. The commit is then
# withheld so unfiltered media never lands; the run reports stage-failed.
HANDOFF_FILTER_FAILED=0
# Skips queued as "reason<TAB>path" lines and written with one jq call, so a
# large skip list does not cost a jq process per path.
HANDOFF_SKIP_QUEUE_FILE=""
handoff_queue_skip() { # handoff_queue_skip <reason> <path>
  [[ -n "$HANDOFF_SKIP_QUEUE_FILE" ]] || new_tmp HANDOFF_SKIP_QUEUE_FILE
  printf '%s\t%s\n' "$1" "$2" >> "$HANDOFF_SKIP_QUEUE_FILE"
  HANDOFF_STAGE_SKIPS=$((HANDOFF_STAGE_SKIPS+1))
}
handoff_flush_skips() {
  [[ -n "$HANDOFF_SKIP_QUEUE_FILE" && -s "$HANDOFF_SKIP_QUEUE_FILE" ]] || return 0
  jq -Rc 'split("\t") | {path: (.[1:] | join("\t")), reason: .[0]}' \
    "$HANDOFF_SKIP_QUEUE_FILE" >> "$SKIPPED_NDJSON_FILE"
}
# handoff_norm_path <path> — sets HANDOFF_NORM to the path with `//` and `/./`
# collapsed, leading `./` and trailing `/` removed. Sets a global instead of
# printing so the staging loop does not fork a subshell per path.
handoff_norm_path() {
  local p="$1" dd='//' dsd='/./' s='/'
  while [[ "$p" == *"$dd"* ]]; do p="${p//$dd/$s}"; done
  while [[ "$p" == *"$dsd"* ]]; do p="${p//$dsd/$s}"; done
  while [[ "$p" == ./* ]]; do p="${p#./}"; done
  while [[ "$p" == */ && "$p" != "/" ]]; do p="${p%/}"; done
  HANDOFF_NORM="$p"
}
handoff_note_added() {
  printf '%s\0' "$1" >> "$HANDOFF_ADDED_PATHS_FILE"
  handoff_norm_path "$1"
  HANDOFF_ADDED_PATHS="${HANDOFF_ADDED_PATHS}${HANDOFF_NORM}"$'\n'
}
handoff_is_media() {
  local rc=1 restore_nocase=0
  shopt -q nocasematch || { shopt -s nocasematch; restore_nocase=1; }
  case "$1" in
    *.mp4|*.mov|*.m4v|*.avi|*.mkv|*.webm|*.wmv|*.flv|*.mpg|*.mpeg|*.prores|\
    *.wav|*.mp3|*.m4a|*.aac|*.flac|*.aif|*.aiff|*.ogg|*.opus|\
    *.png|*.jpg|*.jpeg|*.gif|*.webp|*.heic|*.heif|*.tif|*.tiff|*.bmp|*.psd|*.exr|*.raw|\
    *.zip|*.tar|*.gz|*.tgz|*.bz2|*.xz|*.7z|*.rar|*.dmg|*.iso)
      rc=0 ;;
  esac
  [[ $restore_nocase -eq 0 ]] || shopt -u nocasematch
  return $rc
}
# The handoff's own metadata (thread files, pointer, indexes) and offload
# placeholders always commit, whatever the size cap.
handoff_is_exempt() {
  case "$1" in
    *.hqcloud|workspace/threads/*|workspace/orchestrator/INDEX.md|INDEX.md) return 0 ;;
  esac
  return 1
}
handoff_filter_failed() { # handoff_filter_failed <what failed>
  HANDOFF_FILTER_FAILED=1
  STAGE_FAILURES="${STAGE_FAILURES}handoff-filter: $1"$'\n'
  STAGE_FAILURE_COUNT=$((STAGE_FAILURE_COUNT+1))
  # Best effort: leave nothing unfiltered staged for a later commit to pick up.
  hq_git_index_retry git reset -q --pathspec-from-file="$HANDOFF_ADDED_PATHS_FILE" --pathspec-file-nul >/dev/null 2>&1 || true
}
# handoff_add_ignored_dir <dir> — an ignored directory that holds tracked
# files. Update only what is already tracked; `git add -f` here would force
# every ignored render under it into history (feedback_c682f3ad). Untracked
# ignored entries are reported as skipped instead of dropped silently.
# --directory collapses a wholly untracked subdirectory into one entry.
handoff_add_ignored_dir() {
  local p="$1" f
  hq_git_index_retry git add -u -- "$p" >/dev/null 2>"$STAGE_ERR_FILE" || return 1
  while IFS= read -r -d '' f; do
    [[ -n "$f" ]] || continue
    handoff_queue_skip "ignored-untracked" "$f"
  done < <(git ls-files -z -o -i --exclude-standard --directory -- "$p" 2>/dev/null)
  return 0
}
# handoff_unstage_unwanted — inspect what the staging loop added at or under
# the changeset paths and unstage what the rules above exclude. Sizes come from
# the staged blobs, not the working tree, so a path spelled `a/./b` or in
# another Unicode form cannot dodge the cap, and deleted files need no stat.
handoff_unstage_unwanted() {
  [[ -n "$HANDOFF_ADDED_PATHS_FILE" && -s "$HANDOFF_ADDED_PATHS_FILE" ]] || return 0
  local raw_file renames_file shas_file sizes_file unstage_file
  local meta rest path status size reason renamed n=0 i=0
  local -a h_paths=() h_status=()
  new_tmp raw_file
  new_tmp renames_file
  new_tmp shas_file
  new_tmp sizes_file
  new_tmp unstage_file
  if ! xargs -0 git diff --cached --raw -z --no-abbrev --no-renames --diff-filter=AMT -- \
      < "$HANDOFF_ADDED_PATHS_FILE" > "$raw_file" 2>/dev/null; then
    handoff_filter_failed "could not list staged changes"
    return 0
  fi
  # A tracked file moved to a new name shows as a rename here. Its destination
  # is not new media and must stay staged next to the staged deletion.
  if ! xargs -0 git diff --cached -z --name-status -M --diff-filter=R -- \
      < "$HANDOFF_ADDED_PATHS_FILE" > "$renames_file" 2>/dev/null; then
    handoff_filter_failed "could not list staged renames"
    return 0
  fi
  renamed=$'\n'
  while IFS= read -r -d '' status && IFS= read -r -d '' rest && IFS= read -r -d '' path; do
    renamed="${renamed}${path}"$'\n'
  done < "$renames_file"
  # --raw -z: ":<mode> <mode> <sha> <sha> <status>" NUL "<path>" NUL.
  while IFS= read -r -d '' meta && IFS= read -r -d '' path; do
    status="${meta##* }"
    rest="${meta% *}"
    printf '%s\n' "${rest##* }" >> "$shas_file"
    h_paths[n]="$path"
    h_status[n]="$status"
    n=$((n+1))
  done < "$raw_file"
  [[ $n -gt 0 ]] || return 0
  # One cat-file call sizes every staged blob, in input order. A gitlink or
  # missing object prints a non-numeric line and counts as size 0.
  if ! git cat-file --batch-check='%(objectsize)' < "$shas_file" > "$sizes_file" 2>/dev/null; then
    handoff_filter_failed "could not size staged files"
    return 0
  fi
  while IFS= read -r size && [[ $i -lt $n ]]; do
    path="${h_paths[i]}"
    status="${h_status[i]}"
    i=$((i+1))
    handoff_is_exempt "$path" && continue
    [[ "$size" =~ ^[0-9]+$ ]] || size=0
    reason=""
    [[ $size -gt $HANDOFF_MAX_BYTES ]] && reason="oversize"
    # Only new media is swept in by a directory. A media file the changeset
    # names directly still commits.
    if [[ -z "$reason" && "$status" == "A" && "${HQ_HANDOFF_ALLOW_MEDIA:-}" != "1" ]] \
       && handoff_is_media "$path"; then
      case $'\n'"$HANDOFF_ADDED_PATHS"$renamed in
        *$'\n'"$path"$'\n'*) ;;
        *) reason="media-in-directory" ;;
      esac
    fi
    [[ -n "$reason" ]] || continue
    printf '%s\0' "$path" >> "$unstage_file"
    handoff_queue_skip "$reason" "$path"
  done < "$sizes_file"
  if [[ $i -ne $n ]]; then
    handoff_filter_failed "sized ${i} of ${n} staged files"
    return 0
  fi
  if [[ -s "$unstage_file" ]] \
     && ! hq_git_index_retry git reset -q --pathspec-from-file="$unstage_file" --pathspec-file-nul >/dev/null 2>&1; then
    handoff_filter_failed "could not unstage filtered files"
  fi
  return 0
}
# Newline-separated, not an array: `${#arr[@]}` on an empty array is an unbound
# variable under bash 3.2 + `set -u` (the same trap the SAFE_STAGE_PATHS
# regression hit), and macOS still ships bash 3.2.
STAGE_FAILURES=""
STAGE_FAILURE_COUNT=0
# git's stderr for the first rejected path. It used to go to /dev/null, so a
# sandbox permission denial on .git read as an unexplained "git add failed for
# N path(s)" (feedback_98f2ce49-5065-4670-8544-1a3dccd9985e).
FIRST_STAGE_ERROR=""
STAGE_FAILURE_CLASS=""
new_tmp STAGE_ERR_FILE
NESTED_REPO_PATHS=""
NESTED_DIRTY_MSG=""
# nested_repo_root <path> -> prints the gitlink (a nested repository the HQ
# index records, such as companies/<co>/knowledge) that contains <path>, or
# nothing. A nested repo that is only excluded or ignored (repos/, info/exclude)
# is not a gitlink; its paths keep the ordinary ignored-path handling below. `git add` from the
# HQ root cannot stage a path inside one (feedback d4fcd2e4, 121735c2).
# Gitlinks are listed once up front, so the per-path walk runs no git
# command (it still costs one subshell per path for the substitution).
HQ_GITLINKS=""
if [[ "$HAS_GIT_CHECKOUT" == "true" ]]; then
  HQ_GITLINKS="$(git ls-files -s 2>/dev/null | awk '$1 == "160000" { sub(/^[^\t]*\t/, ""); print }')"
fi
nested_repo_root() {
  local d="$1"
  while [[ "$d" == */* ]]; do
    d="${d%/*}"
    [[ -n "$d" ]] || break
    if [[ -n "$HQ_GITLINKS" ]]; then
      case $'\n'"$HQ_GITLINKS"$'\n' in
        *$'\n'"$d"$'\n'*) printf '%s' "$d"; return 0 ;;
      esac
    fi
  done
  return 0
}
# record_stage_failure <path> — append the path; keep the first stderr line.
record_stage_failure() {
  STAGE_FAILURES="${STAGE_FAILURES}${1}"$'\n'
  STAGE_FAILURE_COUNT=$((STAGE_FAILURE_COUNT+1))
  if [[ -z "$FIRST_STAGE_ERROR" ]]; then
    FIRST_STAGE_ERROR="$(grep -v '^[[:space:]]*$' "$STAGE_ERR_FILE" 2>/dev/null | head -n 1 | tr -d '\r' | cut -c1-300 || true)"
  fi
}
if [[ "$HAS_GIT_CHECKOUT" == "true" ]]; then
  # Changeset paths are file names, never globs: a file named `d/*` must not
  # stage all of d/. Restored after the filter.
  HANDOFF_PRIOR_LITERAL="${GIT_LITERAL_PATHSPECS-__unset__}"
  export GIT_LITERAL_PATHSPECS=1
  for p in "${EXPLICIT_PATHS[@]}"; do
    [[ -n "$p" ]] || continue
    nested="$(nested_repo_root "$p")"
    if [[ -n "$nested" ]]; then
      # The owning repository saves its own files (the knowledge helper commits
      # them there). The HQ root can only record the nested repo's pointer, so
      # stage that and report an inner file that is still uncommitted by name.
      inner="${p#"$nested"/}"
      if [[ -n "$(GIT_LITERAL_PATHSPECS=1 git -C "$nested" status --porcelain -- "$inner" 2>/dev/null)" ]]; then
        record_stage_failure "$p"
        NESTED_DIRTY_MSG="${NESTED_DIRTY_MSG:+$NESTED_DIRTY_MSG; }$p is uncommitted inside nested repository $nested (commit it there, then re-run)"
        continue
      fi
      case $'\n'"$NESTED_REPO_PATHS" in *$'\n'"$p"$'\n'*) ;; *) NESTED_REPO_PATHS="${NESTED_REPO_PATHS}${p}"$'\n' ;; esac
      if [[ -n "$(GIT_LITERAL_PATHSPECS=1 git status --porcelain --ignore-submodules=untracked -- "$nested" 2>/dev/null)" ]] \
         && GIT_LITERAL_PATHSPECS=1 git ls-files --error-unmatch -- "$nested" >/dev/null 2>&1; then
        if GIT_LITERAL_PATHSPECS=1 hq_git_index_retry git add -- "$nested" >/dev/null 2>"$STAGE_ERR_FILE"; then
          STAGED=$((STAGED+1))
          handoff_note_added "$nested"
        else
          record_stage_failure "$nested"
        fi
      fi
      continue
    fi
    if [[ -e "$p" || -n "$(git status --porcelain -- "$p" 2>/dev/null)" ]]; then
      add_rc=0
      hq_git_index_retry git add -- "$p" >/dev/null 2>"$STAGE_ERR_FILE" || add_rc=$?
      if [[ $add_rc -eq 0 ]]; then
        STAGED=$((STAGED+1))
        handoff_note_added "$p"
      elif [[ -d "$p" ]] && GIT_LITERAL_PATHSPECS=0 git check-ignore --no-index -q -- "$p" 2>/dev/null \
           && git ls-files --error-unmatch -- "$p" >/dev/null 2>&1; then
        # An ignored DIRECTORY that holds tracked files. check-ignore rejects
        # literal pathspec magic, hence the override; it takes plain paths.
        if handoff_add_ignored_dir "$p"; then
          STAGED=$((STAGED+1))
          handoff_note_added "$p"
        else
          record_stage_failure "$p"
        fi
      elif [[ ! -d "$p" ]] && git ls-files --error-unmatch -- "$p" >/dev/null 2>&1; then
        # The path is already TRACKED but a broad later ignore rule now shadows it
        # (the scaffold's /workspace/ entry over the tracked handoff pointer/index
        # files), so a plain `git add` refuses it. A tracked file must still be
        # committed, so force-add it. Only a force-add that ALSO fails (e.g. a held
        # .git/index.lock) is a genuine stage failure. Never for a directory:
        # `git add -f` there would force in every ignored file under it, and a
        # directory whose plain add failed for another reason (an unreadable
        # file) is a stage failure below.
        if hq_git_index_retry git add -f -- "$p" >/dev/null 2>"$STAGE_ERR_FILE"; then
          STAGED=$((STAGED+1))
          handoff_note_added "$p"
        else
          record_stage_failure "$p"
        fi
      elif GIT_LITERAL_PATHSPECS=0 git check-ignore --no-index -q -- "$p" 2>/dev/null; then
        # An UNtracked, gitignored path is a deliberate exclusion, not a failed
        # write. --no-index is required: plain `git check-ignore` SKIPS tracked
        # files (it would wrongly report a tracked-but-ignored path as not-ignored,
        # the bug that made this a stage-failure); the tracked case is handled above.
        :
      else
        record_stage_failure "$p"
      fi
    fi
  done
  handoff_unstage_unwanted
  if [[ "$HANDOFF_PRIOR_LITERAL" == "__unset__" ]]; then
    unset GIT_LITERAL_PATHSPECS
  else
    export GIT_LITERAL_PATHSPECS="$HANDOFF_PRIOR_LITERAL"
  fi
fi
handoff_flush_skips
# Fold the staging skips into skipped_paths. It was materialized earlier for
# the thread file; the emitted payload reads the file again below.
if [[ $HANDOFF_STAGE_SKIPS -gt 0 && -s "$SKIPPED_NDJSON_FILE" ]]; then
  jq -s '.' "$SKIPPED_NDJSON_FILE" > "$SKIPPED_PATHS_FILE"
fi
if [[ $STAGE_FAILURE_COUNT -gt 0 ]]; then
  case "$FIRST_STAGE_ERROR" in
    *"Operation not permitted"*|*"Permission denied"*|*"Read-only file system"*)
      STAGE_FAILURE_CLASS="permission" ;;
    *index.lock*) STAGE_FAILURE_CLASS="index-lock" ;;
    *) STAGE_FAILURE_CLASS="other" ;;
  esac
fi
# committed_paths scales with the staged set; capture it to a file (git piped to
# jq via stdin, then the result written to disk) so it too stays off argv.
new_tmp COMMITTED_PATHS_FILE
printf '[]' > "$COMMITTED_PATHS_FILE"
new_tmp STAGE_FAILURES_FILE
printf '[]' > "$STAGE_FAILURES_FILE"
if [[ -n "$STAGE_FAILURES" ]]; then
  printf '%s' "$STAGE_FAILURES" \
    | jq -R -s 'split("\n") | map(select(length > 0))' > "$STAGE_FAILURES_FILE"
fi
# `git diff` has no --pathspec-from-file, and a large changeset must stay off
# argv, so feed this run's own paths through xargs (it splits an oversize list
# into several git calls). A listed directory covers the files staged under it
# (minus what the filter above unstaged); a staged nested-repo gitlink matches
# itself. The result is this run's staged FILES, one per line; paths someone
# else staged are not part of it.
new_tmp OWN_STAGED_CHANGES_FILE
: > "$OWN_STAGED_CHANGES_FILE"
if [[ $STAGED -gt 0 && -s "$OWN_STAGED_FILE" ]]; then
  GIT_LITERAL_PATHSPECS=1 xargs -0 git -c core.quotePath=false diff --cached --name-only --no-renames -- \
    < "$OWN_STAGED_FILE" 2>/dev/null | awk 'NF && !seen[$0]++' > "$OWN_STAGED_CHANGES_FILE" || true
fi
if [[ $STAGED -gt 0 && $HANDOFF_FILTER_FAILED -eq 0 ]] && [[ -s "$OWN_STAGED_CHANGES_FILE" ]]; then
  # Snapshot this run's staged set separately. It only becomes committed_paths
  # once the commit actually lands; a refused commit must not report paths as
  # committed.
  new_tmp PENDING_PATHS_FILE
  jq -R -s 'split("\n") | map(select(length > 0))' < "$OWN_STAGED_CHANGES_FILE" > "$PENDING_PATHS_FILE"
  commit_out=""
  commit_rc=0
  # This commit runs hooks. When the HQ git-hooks dispatcher is installed (a
  # global core.hooksPath), its commit-msg hook stamps HQ-Fingerprint, so an
  # explicit trailer here would be a second copy. Pass it only when no global
  # hooks path is set, i.e. the dispatcher is absent. A lib that fails to
  # source or load leaves the array empty and never aborts the commit.
  HQ_FINGERPRINT_TRAILER_ARGS=()
  if [[ -z "$(git config --global --get core.hooksPath 2>/dev/null || true)" ]] \
     && [[ -f "$HANDOFF_SCRIPT_DIR/lib/fingerprint.sh" ]]; then
    # shellcheck source=lib/fingerprint.sh
    { source "$HANDOFF_SCRIPT_DIR/lib/fingerprint.sh" 2>/dev/null \
        && hq_fingerprint_trailer_load "$HQ_ROOT"; } || HQ_FINGERPRINT_TRAILER_ARGS=()
  fi
  # When the index holds only this run's changes, a plain commit is exact and
  # fast. When something else is staged too, commit --only this run's paths so
  # the foreign entries stay staged and out of the handoff commit. (--only
  # matches every index entry against every pathspec, so it is not used for
  # the common case, where a large changeset would make it quadratic.)
  # The pathspec lists the staged FILES, never a listed directory: --only takes
  # a path's working-tree state, so a directory pathspec would pull back in a
  # file the media/oversize filter just unstaged.
  COMMIT_SCOPE_ARGS=()
  if [[ "$(git diff --cached --name-only --no-renames 2>/dev/null | wc -l | tr -d ' ')" != "$(jq 'length' "$PENDING_PATHS_FILE")" ]]; then
    new_tmp COMMIT_PATHSPEC_FILE
    tr '\n' '\0' < "$OWN_STAGED_CHANGES_FILE" > "$COMMIT_PATHSPEC_FILE"
    COMMIT_SCOPE_ARGS=(--only --pathspec-from-file="$COMMIT_PATHSPEC_FILE" --pathspec-file-nul)
  fi
  new_tmp COMMIT_OUT_FILE
  GIT_LITERAL_PATHSPECS=1 hq_git_index_retry git commit ${COMMIT_SCOPE_ARGS[@]+"${COMMIT_SCOPE_ARGS[@]}"} -m "checkpoint: handoff ${THREAD_ID}" ${HQ_FINGERPRINT_TRAILER_ARGS[@]+"${HQ_FINGERPRINT_TRAILER_ARGS[@]}"} >"$COMMIT_OUT_FILE" 2>&1 || commit_rc=$?
  commit_out="$(cat "$COMMIT_OUT_FILE" 2>/dev/null || true)"
  if [[ $commit_rc -eq 0 ]]; then
    HQ_COMMITTED="true"
    HQ_COMMIT_STATUS="committed"
    cat "$PENDING_PATHS_FILE" > "$COMMITTED_PATHS_FILE"
  else
    HQ_COMMIT_STATUS="failed"
    HQ_COMMIT_ERROR="$(printf '%s' "$commit_out" | tr '\r\n' '  ' | sed 's/  */ /g; s/^ //; s/ $//' | cut -c1-500)"
    [[ -n "$HQ_COMMIT_ERROR" ]] || HQ_COMMIT_ERROR="git commit exited ${commit_rc} with no output"
  fi
fi
# A staging failure is just as fatal as a refused commit, and it is the shape a
# held .git/index.lock actually takes: every `git add` fails, STAGED stays 0, no
# commit is even attempted, and the run would otherwise look like the benign
# "nothing to commit" case while the entire handoff sits uncommitted on disk.
if [[ $STAGE_FAILURE_COUNT -gt 0 && "$HQ_COMMIT_STATUS" != "failed" ]]; then
  HQ_COMMIT_STATUS="stage-failed"
  if [[ -z "$HQ_COMMIT_ERROR" ]]; then
    HQ_COMMIT_ERROR="git add failed for ${STAGE_FAILURE_COUNT} path(s) — see stage_failures"
    case "$STAGE_FAILURE_CLASS" in
      permission)
        HQ_COMMIT_ERROR="${HQ_COMMIT_ERROR}; permission denied writing the git repository (a sandboxed run cannot write .git; re-run /handoff outside the sandbox)" ;;
      index-lock)
        HQ_COMMIT_ERROR="${HQ_COMMIT_ERROR}; another git process holds .git/index.lock (wait for it and re-run /handoff)" ;;
    esac
    [[ -z "$FIRST_STAGE_ERROR" ]] || HQ_COMMIT_ERROR="${HQ_COMMIT_ERROR}; first git error: ${FIRST_STAGE_ERROR}"
    [[ -z "$NESTED_DIRTY_MSG" ]] || HQ_COMMIT_ERROR="${HQ_COMMIT_ERROR}: ${NESTED_DIRTY_MSG}"
  fi
fi
COMMIT_AFTER=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")

# -------- publish continuity pointer to the personal vault (cross-device) --------
# workspace/ is otherwise excluded from the personal vault; only handoff.json
# plus the referenced thread file are carved in (hq-cloud-sync
# computeContinuityPointerPaths). Without a push between A's /handoff and B's
# /startwork, machine B sees stale state. Fire the publisher in the background
# so handoff never blocks on cloud reachability. Fail-soft: a missing hq CLI,
# an offline host, or a logged-out operator all exit 0 inside the helper.
HANDOFF_PUBLISH_PID=""
HANDOFF_PUBLISH_STATUS="skipped"
_PUBLISH_SH="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/handoff-sync-publish.sh"
if [[ "$HQ_COMMITTED" == "true" && -f "$_PUBLISH_SH" ]]; then
  HANDOFF_PUBLISH_PID="$(bash "$_PUBLISH_SH" --hq-root "$HQ_ROOT" \
    --log /tmp/handoff-sync-publish.log 2>/dev/null || true)"
  if [[ -n "$HANDOFF_PUBLISH_PID" ]]; then
    HANDOFF_PUBLISH_STATUS="dispatched"
  fi
fi

# -------- qmd reindex fire-and-forget (agent: skip; laptop: single-flight) --------
# Agent boxes: managed timer owns indexing — handoff never kicks qmd.
# Laptop: qmd-reindex-bg single-flight reindex. See qmd-reindex-bg.sh.
# Helper is invoked synchronously: it is fail-soft and either prints
# skipped-agent / skipped, or launches its own detached worker and prints a PID.
# qmd_pid must never claim an agent reindex ran.
QMD_PID=""
# Prefer Core US-001 helper; fleet binary only if Core file is missing.
_QMD_BG="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/qmd-reindex-bg.sh"
if [[ ! -f "$_QMD_BG" ]] && [[ -x /usr/local/bin/hq-agent-qmd-reindex-bg ]]; then
  _QMD_BG=/usr/local/bin/hq-agent-qmd-reindex-bg
fi
if [[ -x "$_QMD_BG" ]] || [[ -f "$_QMD_BG" ]]; then
  # bash (not require +x) so a fresh checkout still routes through the helper.
  QMD_PID="$(bash "$_QMD_BG" --log /tmp/qmd-handoff.log 2>/dev/null || true)"
elif [[ -d /var/lib/hq-agent ]]; then
  # Agent box without helper yet: still do not raw-embed.
  QMD_PID="skipped-agent"
fi

# -------- copy next-step command to clipboard (fail-soft) --------
[[ "$NEXT_COMMAND" == "__auto__" ]] && NEXT_COMMAND="/resumework ${THREAD_ID}"
CLIPBOARD_COPIED="false"
if [[ -n "$NEXT_COMMAND" ]]; then
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$NEXT_COMMAND" | pbcopy 2>/dev/null && CLIPBOARD_COPIED="true"
  elif command -v wl-copy >/dev/null 2>&1; then
    printf '%s' "$NEXT_COMMAND" | wl-copy 2>/dev/null && CLIPBOARD_COPIED="true"
  elif command -v xclip >/dev/null 2>&1; then
    printf '%s' "$NEXT_COMMAND" | xclip -selection clipboard 2>/dev/null && CLIPBOARD_COPIED="true"
  fi
fi

# -------- emit result --------
# Git Bash/MSYS rewrites slash-leading argv values for native executables.
# next_command is command text, not a filesystem path; preserve it for jq.
# When cygpath is available, convert the slurpfile paths to native Windows
# paths first so native jq can open them while MSYS_NO_PATHCONV protects the
# slash-leading command text. On POSIX systems the paths stay unchanged.
jq_slurpfile_path() {
  local path="$1"
  if command -v cygpath >/dev/null 2>&1; then
    cygpath -m "$path"
  else
    printf '%s\n' "$path"
  fi
}
COMMITTED_PATHS_JQ_FILE="$(jq_slurpfile_path "$COMMITTED_PATHS_FILE")"
STAGE_FAILURES_JQ_FILE="$(jq_slurpfile_path "$STAGE_FAILURES_FILE")"
SKIPPED_PATHS_JQ_FILE="$(jq_slurpfile_path "$SKIPPED_PATHS_FILE")"
MSYS_NO_PATHCONV=1 jq -n \
  --arg thread_id "$THREAD_ID" \
  --arg thread_path "$THREAD_PATH" \
  --arg handoff_path "workspace/threads/handoff.json" \
  --argjson hq_committed "$HQ_COMMITTED" \
  --argjson indexes_regen "true" \
  --arg qmd_pid "${QMD_PID:-}" \
  --arg git_bg_errors "$GIT_BG_ERRORS" \
  --arg changeset_path "$CHANGESET_PATH" \
  --arg hq_commit_status "$HQ_COMMIT_STATUS" \
  --arg hq_commit_error "$HQ_COMMIT_ERROR" \
  --slurpfile committed_paths "$COMMITTED_PATHS_JQ_FILE" \
  --slurpfile stage_failures "$STAGE_FAILURES_JQ_FILE" \
  --arg stage_failure_class "$STAGE_FAILURE_CLASS" \
  --argjson index_lock_waits "$HQ_HANDOFF_INDEX_LOCK_WAITS" \
  --slurpfile skipped_paths "$SKIPPED_PATHS_JQ_FILE" \
  --arg nested_repo_paths "$NESTED_REPO_PATHS" \
  --argjson baseline_noise_count "$BASELINE_NOISE_COUNT" \
  --arg commit_after_finalize "$COMMIT_AFTER" \
  --arg next_command "$NEXT_COMMAND" \
  --argjson clipboard_copied "$CLIPBOARD_COPIED" \
  --argjson mirror_companies "$MIRRORED_COMPANIES_JSON" \
  --arg handoff_publish_pid "${HANDOFF_PUBLISH_PID:-}" \
  --arg handoff_publish_status "${HANDOFF_PUBLISH_STATUS:-skipped}" \
  '{
    thread_id: $thread_id,
    thread_path: $thread_path,
    changeset_path: $changeset_path,
    handoff_path: $handoff_path,
    hq_committed: $hq_committed,
    hq_commit_status: $hq_commit_status,
    hq_commit_error: $hq_commit_error,
    commit_after_finalize: $commit_after_finalize,
    committed_paths: ($committed_paths[0] // []),
    stage_failures: ($stage_failures[0] // []),
    stage_failure_class: $stage_failure_class,
    index_lock_waits: $index_lock_waits,
    skipped_paths: ($skipped_paths[0] // []),
    nested_repo_paths: ($nested_repo_paths | split("\n") | map(select(length > 0))),
    baseline_noise_count: $baseline_noise_count,
    indexes_regen: $indexes_regen,
    qmd_pid: $qmd_pid,
    git_bg_errors: $git_bg_errors,
    next_command: $next_command,
    clipboard_copied: $clipboard_copied,
    mirror_companies: $mirror_companies,
    handoff_publish_pid: $handoff_publish_pid,
    handoff_publish_status: $handoff_publish_status
  }'

# -------- fail loudly on a git write that did not land --------
# The payload above is always emitted first: the caller still needs the thread
# id and paths to recover. What changes is that a refused commit no longer
# leaves the process looking successful.
if [[ -n "$GIT_BG_ERRORS" ]]; then
  echo "handoff-finalize: WARNING background git step reported errors: $GIT_BG_ERRORS" >&2
fi
if [[ $STAGE_FAILURE_COUNT -gt 0 ]]; then
  echo "handoff-finalize: ERROR git add failed for ${STAGE_FAILURE_COUNT} path(s):" >&2
  printf '%s' "$STAGE_FAILURES" | sed 's/^/handoff-finalize:   /' >&2
fi
case "$HQ_COMMIT_STATUS" in
  failed|stage-failed)
    echo "handoff-finalize: ERROR the HQ handoff commit FAILED — thread files were written but are NOT committed." >&2
    echo "handoff-finalize: git said: $HQ_COMMIT_ERROR" >&2
    echo "handoff-finalize: resolve the git error and re-run /handoff before ending the session." >&2
    exit 4
    ;;
esac
exit 0
